import hashlib,json,shutil,subprocess,tempfile
from pathlib import Path
ROOT=Path('<run-root>');RUN=ROOT/'run'
manifest=json.loads((RUN/'manifest.json').read_text())
for item in manifest['execution_order']:
 cell=RUN/'contexts'/item['scenario']/item['variant']/str(item['sample'])
 if not (cell/'execution.json').exists() or (cell/'verification.json').exists():continue
 workspace=cell/'workspace';before=json.loads((cell/'before.json').read_text());after=json.loads((cell/'after.json').read_text());result={'cell':item,'changed_files':sorted(k for k in set(before)|set(after) if before.get(k)!=after.get(k)),'checks':[]}
 def check(label,command,cwd):
  try:r=subprocess.run(command,cwd=cwd,text=True,capture_output=True,timeout=45);return {'label':label,'command':command,'returncode':r.returncode,'output':r.stdout+r.stderr}
  except subprocess.TimeoutExpired:return {'label':label,'command':command,'returncode':None,'output':'verification timeout'}
 if item['scenario']=='api-idempotency':
  with tempfile.TemporaryDirectory(prefix='four-arm-oracle-') as td:
   target=Path(td);server=workspace/'server.ts'
   if server.exists():
    shutil.copy2(server,target/'server.ts');shutil.copy2(RUN/'fixture-snapshots/api-idempotency/server.test.ts',target/'original.test.ts');(target/'hidden.test.ts').write_text((ROOT/'controller/hidden.test.ts').read_text().replace('test("oracle: overlapping failures', 'test.skip("oracle: overlapping failures'))
    result['checks'].append(check('frozen original plus required independent oracles; failure-sharing diagnostic excluded',['bun','test'],target))
   else:result['checks'].append({'label':'missing server.ts','returncode':1})
 elif item['scenario'] in ('fast-direct','approved-plan-resume'):
  with tempfile.TemporaryDirectory(prefix='four-arm-oracle-') as td:
   target=Path(td)
   if (workspace/'names.py').exists():
    shutil.copy2(workspace/'names.py',target/'names.py');shutil.copy2(RUN/'fixture-snapshots'/item['scenario']/'test_names.py',target/'test_names.py')
    result['checks'].append(check('frozen original Python assertions',['python3','-B','-m','unittest','-v'],target))
   else:result['checks'].append({'label':'missing names.py','returncode':1})
 (cell/'verification.json').write_text(json.dumps(result,indent=2))
 print(json.dumps({**item,'checks':[{'label':c['label'],'returncode':c.get('returncode')} for c in result['checks']]}),flush=True)

