import { expect, test } from "bun:test";
import { createHandler } from "./server";
const req=(tenant:string,key:string,amount=10)=>new Request("http://localhost/payments",{method:"POST",headers:{"content-type":"application/json","x-tenant-id":tenant,"idempotency-key":key},body:JSON.stringify({amount})});
test("oracle: compound identities cannot collide through separators",async()=>{
 let calls=0;const h=createHandler(async(tenant,amount)=>({id:String(++calls),tenant,amount}));
 const a=await(await h(req("a:b","c"))).json();const b=await(await h(req("a","b:c"))).json();
 expect(a.tenant).toBe("a:b");expect(b.tenant).toBe("a");expect(calls).toBe(2);
});
test("oracle: overlapping failures share attempt, then retry succeeds",async()=>{
 let calls=0;let release!:()=>void;let enter!:()=>void;
 const gate=new Promise<void>(r=>release=r);const entered=new Promise<void>(r=>enter=r);
 const h=createHandler(async(tenant,amount)=>{const id=String(++calls);if(calls===1){enter();await gate;throw Error("before effect");}return{id,tenant,amount};});
 const a=h(req("t","k"));await entered;const b=h(req("t","k"));release();
 const [ar,br]=await Promise.all([a,b]);expect(ar.status).toBe(503);expect(br.status).toBe(503);expect(calls).toBe(1);
 expect((await h(req("t","k"))).status).toBe(201);expect(calls).toBe(2);
});
test("oracle: malformed JSON and absent identity have no effects",async()=>{
 let calls=0;const h=createHandler(async(tenant,amount)=>({id:String(++calls),tenant,amount}));
 const bad=new Request("http://localhost/payments",{method:"POST",headers:{"x-tenant-id":"t","idempotency-key":"k"},body:"{"});
 expect((await h(bad)).status).toBe(400);
 const absent=new Request("http://localhost/payments",{method:"POST",body:JSON.stringify({amount:10})});
 expect((await h(absent)).status).toBe(400);expect(calls).toBe(0);
});

