function deferred<T>() {
  let resolve!: (value: T | PromiseLike<T>) => void;
  let reject!: (reason: unknown) => void;
  const promise = new Promise<T>((yes, no) => { resolve = yes; reject = no; });
  return { promise, resolve, reject };
}

describe("idempotency edge cases", () => {
  test("rejects malformed JSON, invalid amounts and missing identities before effects", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    const bodies = ["{", "null", "[]", "{}", '{"amount":"10"}', '{"amount":null}',
      '{"amount":0}', '{"amount":-1}', '{"amount":1e400}', '{"amount":-1e400}'];
    for (const body of bodies) {
      const invalid = new Request("http://localhost/payments", {
        method: "POST", headers: { "x-tenant-id": "tenant-a", "idempotency-key": "key-1" }, body,
      });
      expect((await handler(invalid)).status).toBe(400);
    }
    for (const header of ["x-tenant-id", "idempotency-key"]) {
      const missing = request();
      missing.headers.delete(header);
      expect((await handler(missing)).status).toBe(400);
      const empty = request();
      empty.headers.set(header, "");
      expect((await handler(empty)).status).toBe(400);
    }
    expect(calls).toBe(0);
    expect((await handler(request("tenant-a", 0.01))).status).toBe(201);
    expect(calls).toBe(1);
  });

  test("preserves routing and response contracts", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    expect((await handler(new Request("http://localhost/payments"))).status).toBe(404);
    expect((await handler(new Request("http://localhost/other", { method: "POST" }))).status).toBe(404);
    expect(calls).toBe(0);
    const first = await handler(request());
    const replay = await handler(request());
    expect(first.status).toBe(201);
    expect(replay.status).toBe(201);
    expect(first.headers.get("content-type")).toContain("application/json");
    expect(await first.json()).toEqual({ id: "1", tenant: "tenant-a", amount: 10 });
    expect(await replay.json()).toEqual({ id: "1", tenant: "tenant-a", amount: 10 });
  });

  test("handles a burst of identical requests with a single effect", async () => {
    let calls = 0;
    const gate = deferred<void>();
    const started = deferred<void>();
    const handler = createHandler(async (tenant, amount) => {
      const id = String(++calls);
      started.resolve();
      await gate.promise;
      return { id, tenant, amount };
    });
    const pending = Array.from({ length: 100 }, () => handler(request()));
    await started.promise;
    gate.resolve();
    const responses = await Promise.all(pending);
    for (const response of responses) {
      expect(response.status).toBe(201);
      expect(await response.json()).toEqual({ id: "1", tenant: "tenant-a", amount: 10 });
    }
    expect(calls).toBe(1);
  });

  test("other tenants and keys progress while one effect is pending", async () => {
    let calls = 0;
    const gate = deferred<void>();
    const started = deferred<void>();
    const handler = createHandler(async (tenant, amount) => {
      const id = String(++calls);
      if (id === "1") { started.resolve(); await gate.promise; }
      return { id, tenant, amount };
    });
    const first = handler(request());
    await started.promise;
    try {
      const otherTenant = await handler(request("tenant-b", 20));
      const otherKey = await handler(request("tenant-a", 30, "key-2"));
      expect(await otherTenant.json()).toEqual({ id: "2", tenant: "tenant-b", amount: 20 });
      expect(await otherKey.json()).toEqual({ id: "3", tenant: "tenant-a", amount: 30 });
      expect(calls).toBe(3);
    } finally {
      gate.resolve();
      await first;
    }
  });

  test("tenant/key pairs containing separators do not collide", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    for (const [tenant, key] of [["a:b", "c"], ["a", "b:c"], ["a|b", "c"], ["a", "b|c"]]) {
      const response = await handler(request(tenant, 10, key));
      expect(response.status).toBe(201);
      expect((await response.json()).tenant).toBe(tenant);
    }
    expect(calls).toBe(4);
  });

  test("shares failure among concurrent callers, then allows a fresh reservation", async () => {
    let calls = 0;
    let parsed = 0;
    const allParsed = deferred<void>();
    const gate = deferred<void>();
    const started = deferred<void>();
    const handler = createHandler(async (tenant, amount) => {
      const id = String(++calls);
      if (id === "1") { started.resolve(); await gate.promise; }
      return { id, tenant, amount };
    });
    const pending = Array.from({ length: 20 }, () => {
      const value = request();
      value.json = async () => {
        if (++parsed === 20) allParsed.resolve();
        return { amount: 10 };
      };
      return handler(value);
    });
    await allParsed.promise;
    await started.promise;
    gate.reject(new Error("failure before effect"));
    for (const response of await Promise.all(pending)) {
      expect(response.status).toBe(503);
      expect(await response.json()).toEqual({ error: "temporary failure" });
    }
    expect(calls).toBe(1);
    // The failed attempt did not bind the key to its old payload.
    const retry = await handler(request("tenant-a", 20));
    expect(retry.status).toBe(201);
    expect(await retry.json()).toEqual({ id: "2", tenant: "tenant-a", amount: 20 });
    expect((await handler(request("tenant-a", 20))).status).toBe(201);
    expect((await handler(request())).status).toBe(409);
    expect(calls).toBe(2);
  });

  test("synchronous creator failures release the reservation", async () => {
    let calls = 0;
    const handler = createHandler((tenant, amount) => {
      if (++calls === 1) throw new Error("synchronous failure before effect");
      return Promise.resolve({ id: String(calls), tenant, amount });
    });
    expect((await handler(request())).status).toBe(503);
    expect((await handler(request())).status).toBe(201);
    expect(calls).toBe(2);
  });
});

