export type Payment = { id: string; tenant: string; amount: number };
export type CreatePayment = (tenant: string, amount: number) => Promise<Payment>;

export function createHandler(createPayment: CreatePayment) {
  type Entry = { amount: number; result: Promise<Payment> };
  const tenants = new Map<string, Map<string, Entry>>();
  return async (request: Request): Promise<Response> => {
    const url = new URL(request.url);
    if (request.method !== "POST" || url.pathname !== "/payments") {
      return Response.json({ error: "not found" }, { status: 404 });
    }
    const tenant = request.headers.get("x-tenant-id");
    const key = request.headers.get("idempotency-key");
    let body: unknown;
    try { body = await request.json(); }
    catch { return Response.json({ error: "invalid JSON" }, { status: 400 }); }
    const amount = (body as { amount?: unknown } | null)?.amount;
    if (!tenant || !key || typeof amount !== "number" || !Number.isFinite(amount) || amount <= 0) {
      return Response.json({ error: "invalid input" }, { status: 400 });
    }
    let entries = tenants.get(tenant);
    let entry = entries?.get(key);
    if (entry && entry.amount !== amount) {
      return Response.json({ error: "idempotency conflict" }, { status: 409 });
    }
    if (!entry) {
      if (!entries) {
        entries = new Map();
        tenants.set(tenant, entries);
      }
      const tenantEntries = entries;
      // Reserve synchronously; invoke the effect only after the entry is visible.
      // Rejections must mean failure before the effect, so removing permits retry.
      const result = Promise.resolve()
        .then(() => createPayment(tenant, amount))
        .catch(error => {
          tenantEntries.delete(key);
          if (tenantEntries.size === 0) tenants.delete(tenant);
          throw error;
        });
      entry = { amount, result };
      entries.set(key, entry);
    }
    try {
      const payment = await entry.result;
      return Response.json(payment, { status: 201 });
    } catch {
      return Response.json({ error: "temporary failure" }, { status: 503 });
    }
  };
}

if (import.meta.main) {
  let sequence = 0;
  const fetch = createHandler(async (tenant, amount) => ({ id: `synthetic-${++sequence}`, tenant, amount }));
  Bun.serve({ hostname: "127.0.0.1", port: Number(Bun.env.PORT ?? 3000), fetch });
}

