import { describe, expect, test } from "bun:test";
import { createHandler, type Payment } from "./server";

function request(tenant = "tenant-a", amount = 10, key = "key-1") {
  return new Request("http://localhost/payments", {
    method: "POST", headers: { "content-type": "application/json", "x-tenant-id": tenant, "idempotency-key": key },
    body: JSON.stringify({ amount }),
  });
}

describe("synthetic HTTP idempotency acceptance", () => {
  test("validates input before creating a payment", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    expect((await handler(request("tenant-a", -1))).status).toBe(400);
    expect(calls).toBe(0);
  });

  test("replays the same tenant, key and payload without another side effect", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    const first = await (await handler(request())).json();
    expect(await (await handler(request())).json()).toEqual(first);
    expect(calls).toBe(1);
  });

  test("isolates identical keys across tenants", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    await handler(request("tenant-a"));
    const other = await (await handler(request("tenant-b"))).json();
    expect(other.tenant).toBe("tenant-b");
    expect(calls).toBe(2);
  });

  test("rejects changed payload for the same tenant and key", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    await handler(request());
    expect((await handler(request("tenant-a", 20))).status).toBe(409);
    expect(calls).toBe(1);
  });

  test("coalesces concurrent identical requests before awaiting the side effect", async () => {
    let calls = 0;
    let release!: () => void;
    const gate = new Promise<void>(resolve => { release = resolve; });
    const handler = createHandler(async (tenant, amount): Promise<Payment> => {
      const id = String(++calls);
      await gate;
      return { id, tenant, amount };
    });
    let parsed = 0;
    let bothParsed!: () => void;
    const parsing = new Promise<void>(resolve => { bothParsed = resolve; });
    const observedRequest = () => {
      const value = request();
      value.json = async () => {
        if (++parsed === 2) bothParsed();
        return { amount: 10 };
      };
      return value;
    };
    const pending = [handler(observedRequest()), handler(observedRequest())];
    await parsing;
    release();
    const responses = await Promise.all(pending);
    expect(await responses[0].json()).toEqual(await responses[1].json());
    expect(calls).toBe(1);
  });

  test("rejects conflicting payload while the original effect is pending", async () => {
    let calls = 0;
    let entered!: () => void;
    let release!: () => void;
    const started = new Promise<void>(resolve => { entered = resolve; });
    const gate = new Promise<void>(resolve => { release = resolve; });
    const handler = createHandler(async (tenant, amount) => {
      const id = String(++calls);
      if (calls === 1) { entered(); await gate; }
      return { id, tenant, amount };
    });
    const original = handler(request());
    await started;
    const conflict = await handler(request("tenant-a", 20));
    release();
    await original;
    expect(conflict.status).toBe(409);
    expect(calls).toBe(1);
  });

  test("allows retry after an unsuccessful side effect", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => {
      if (++calls === 1) throw new Error("synthetic failure before effect");
      return { id: String(calls), tenant, amount };
    });
    expect((await handler(request())).status).toBe(503);
    expect((await handler(request())).status).toBe(201);
    expect(calls).toBe(2);
  });
});

describe("idempotency boundaries and recovery", () => {
  function deferred() {
    let resolve!: () => void;
    const promise = new Promise<void>(done => { resolve = done; });
    return { promise, resolve };
  }

  test("rejects malformed JSON, missing headers and invalid amounts without effects", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    for (const body of ["{", "null", "[]", "{}", '{"amount":0}', '{"amount":-1}',
      '{"amount":"10"}', '{"amount":null}', '{"amount":true}', '{"amount":1e400}']) {
      const invalid = request();
      expect((await handler(new Request(invalid, { body }))).status).toBe(400);
    }
    for (const header of ["x-tenant-id", "idempotency-key"]) {
      for (const missing of [true, false]) {
        const invalid = request();
        if (missing) invalid.headers.delete(header);
        else invalid.headers.set(header, "");
        expect((await handler(invalid)).status).toBe(400);
      }
    }
    expect(calls).toBe(0);
    expect((await handler(request("tenant-a", 0.5))).status).toBe(201);
    expect(calls).toBe(1);
  });

  test("preserves routing and JSON response contracts", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    for (const req of [new Request("http://localhost/payments"),
      new Request("http://localhost/other", { method: "POST" })]) {
      const response = await handler(req);
      expect(response.status).toBe(404);
      expect(await response.json()).toEqual({ error: "not found" });
    }
    expect(calls).toBe(0);
    const first = await handler(request());
    const replay = await handler(request());
    expect(first.status).toBe(201);
    expect(replay.status).toBe(201);
    expect(first.headers.get("content-type")).toContain("application/json");
    expect(await first.json()).toEqual(await replay.json());
    expect(calls).toBe(1);
  });

  test("keeps tenant and key tuples distinct even when they contain separators", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    for (const [tenant, key] of [["a:b", "c"], ["a", "b:c"], ["a|b", "c"], ["a", "b|c"]]) {
      expect((await handler(request(tenant, 10, key))).status).toBe(201);
    }
    expect(calls).toBe(4);
  });

  test("does not block other tenants or keys behind a pending effect", async () => {
    const started = deferred();
    const gate = deferred();
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => {
      const id = String(++calls);
      if (id === "1") { started.resolve(); await gate.promise; }
      return { id, tenant, amount };
    });
    const original = handler(request());
    await started.promise;
    try {
      const otherTenant = await handler(request("tenant-b", 20));
      expect(otherTenant.status).toBe(201);
      expect(await otherTenant.json()).toEqual({ id: "2", tenant: "tenant-b", amount: 20 });
      expect((await handler(request("tenant-a", 30, "key-2"))).status).toBe(201);
      expect(calls).toBe(3);
    } finally { gate.resolve(); await original; }
  });

  test("shares pending failure, then lets a different payload retry and replay", async () => {
    const started = deferred();
    const gate = deferred();
    const joined = deferred();
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => {
      const id = String(++calls);
      if (id === "1") {
        started.resolve();
        await gate.promise;
        throw new Error("failure before effect");
      }
      return { id, tenant, amount };
    });
    const original = handler(request());
    await started.promise;
    const duplicateRequest = request();
    duplicateRequest.json = async () => { joined.resolve(); return { amount: 10 }; };
    const duplicate = handler(duplicateRequest);
    await joined.promise;
    gate.resolve();
    const responses = await Promise.all([original, duplicate]);
    for (const response of responses) {
      expect(response.status).toBe(503);
      expect(await response.json()).toEqual({ error: "temporary failure" });
    }
    expect(calls).toBe(1);
    const retry = await handler(request("tenant-a", 20));
    expect(retry.status).toBe(201);
    expect(await retry.json()).toEqual(await (await handler(request("tenant-a", 20))).json());
    expect((await handler(request())).status).toBe(409);
    expect(calls).toBe(2);
  });

  test("cleans up a synchronous throw before allowing retry", async () => {
    let calls = 0;
    const handler = createHandler((tenant, amount) => {
      if (++calls === 1) throw new Error("synchronous failure before effect");
      return Promise.resolve({ id: String(calls), tenant, amount });
    });
    expect((await handler(request())).status).toBe(503);
    expect((await handler(request())).status).toBe(201);
    expect((await handler(request())).status).toBe(201);
    expect(calls).toBe(2);
  });

  test("coalesces a burst and replays its result", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    const responses = await Promise.all(Array.from({ length: 100 }, () => handler(request())));
    for (const response of responses) {
      expect(response.status).toBe(201);
      expect(await response.json()).toEqual({ id: "1", tenant: "tenant-a", amount: 10 });
    }
    expect((await handler(request())).status).toBe(201);
    expect(calls).toBe(1);
  });
});

