describe("HTTP boundaries and recovery", () => {
  test("rejects invalid amounts, JSON and missing identities without effects", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    for (const body of ["{", "null", "[]", "{}", '{"amount":"10"}', '{"amount":true}',
      '{"amount":null}', '{"amount":0}', '{"amount":-1}', '{"amount":1e309}']) {
      const value = request();
      const invalid = new Request(value.url, { method: "POST", headers: value.headers, body });
      expect((await handler(invalid)).status).toBe(400);
    }
    for (const header of ["x-tenant-id", "idempotency-key"]) {
      for (const missing of [true, false]) {
        const value = request();
        if (missing) value.headers.delete(header);
        else value.headers.set(header, "");
        expect((await handler(value)).status).toBe(400);
      }
    }
    expect(calls).toBe(0);
    expect((await handler(request("tenant-a", Number.MIN_VALUE))).status).toBe(201);
    expect((await handler(request("tenant-a", Number.MAX_VALUE, "max"))).status).toBe(201);
    expect(calls).toBe(2);
  });

  test("preserves route and method handling", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    expect((await handler(new Request("http://localhost/payments"))).status).toBe(404);
    expect((await handler(new Request("http://localhost/other", { method: "POST" }))).status).toBe(404);
    expect(calls).toBe(0);
  });

  test("does not serialize unrelated tenants or keys behind a pending effect", async () => {
    let calls = 0;
    let entered!: () => void;
    let release!: () => void;
    const started = new Promise<void>(resolve => { entered = resolve; });
    const gate = new Promise<void>(resolve => { release = resolve; });
    const handler = createHandler(async (tenant, amount) => {
      const id = String(++calls);
      if (calls === 1) { entered(); await gate; }
      return { id, tenant, amount };
    });
    const original = handler(request());
    await started;
    try {
      expect((await handler(request("tenant-b"))).status).toBe(201);
      expect((await handler(request("tenant-a", 20, "key-2"))).status).toBe(201);
      expect(calls).toBe(3);
    } finally { release(); }
    expect((await original).status).toBe(201);
  });

  test("shares a pending failure, releases the reservation and caches a successful retry", async () => {
    let attempts = 0;
    let effects = 0;
    let entered!: () => void;
    let release!: () => void;
    const started = new Promise<void>(resolve => { entered = resolve; });
    const gate = new Promise<void>(resolve => { release = resolve; });
    const handler = createHandler(async (tenant, amount) => {
      if (++attempts === 1) {
        entered();
        await gate;
        throw new Error("failure before effect");
      }
      return { id: String(++effects), tenant, amount };
    });
    const original = handler(request());
    await started;
    const duplicates = Array.from({ length: 20 }, () => handler(request()));
    try {
      // This request's continuation follows the duplicates' parsing continuations.
      expect((await handler(request("tenant-a", 20))).status).toBe(409);
      expect(attempts).toBe(1);
    } finally { release(); }
    const failed = await Promise.all([original, ...duplicates]);
    expect(failed.every(response => response.status === 503)).toBe(true);
    expect(attempts).toBe(1);
    expect(effects).toBe(0);
    const retried = await handler(request("tenant-a", 20));
    expect(retried.status).toBe(201);
    const payment = await retried.json();
    const replay = await handler(request("tenant-a", 20));
    expect(replay.status).toBe(201);
    expect(await replay.json()).toEqual(payment);
    expect((await handler(request())).status).toBe(409);
    expect(attempts).toBe(2);
    expect(effects).toBe(1);
  });

  test("recovers from a synchronous exception before the effect", async () => {
    let attempts = 0;
    const handler = createHandler((tenant, amount) => {
      if (++attempts === 1) throw new Error("synchronous failure");
      return Promise.resolve({ id: String(attempts), tenant, amount });
    });
    expect((await handler(request())).status).toBe(503);
    expect((await handler(request())).status).toBe(201);
    expect(attempts).toBe(2);
  });

  test("keeps tenant and key tuples distinct even with delimiter characters", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    const first = await (await handler(request("a:b", 10, "c"))).json();
    const second = await (await handler(request("a", 10, "b:c"))).json();
    expect(first.id).not.toBe(second.id);
    expect(second.tenant).toBe("a");
    expect(calls).toBe(2);
  });
});

