import { describe, expect, test } from "bun:test";
import { createHandler, type Payment } from "./server";

function request(tenant = "tenant-a", amount = 10, key = "key-1") {
  return new Request("http://localhost/payments", {
    method: "POST", headers: { "content-type": "application/json", "x-tenant-id": tenant, "idempotency-key": key },
    body: JSON.stringify({ amount }),
  });
}

describe("synthetic HTTP idempotency acceptance", () => {
  test("validates input before creating a payment", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    expect((await handler(request("tenant-a", -1))).status).toBe(400);
    expect(calls).toBe(0);
  });

  test("replays the same tenant, key and payload without another side effect", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    const first = await (await handler(request())).json();
    expect(await (await handler(request())).json()).toEqual(first);
    expect(calls).toBe(1);
  });

  test("isolates identical keys across tenants", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    await handler(request("tenant-a"));
    const other = await (await handler(request("tenant-b"))).json();
    expect(other.tenant).toBe("tenant-b");
    expect(calls).toBe(2);
  });

  test("rejects changed payload for the same tenant and key", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    await handler(request());
    expect((await handler(request("tenant-a", 20))).status).toBe(409);
    expect(calls).toBe(1);
  });

  test("coalesces concurrent identical requests before awaiting the side effect", async () => {
    let calls = 0;
    let release!: () => void;
    const gate = new Promise<void>(resolve => { release = resolve; });
    const handler = createHandler(async (tenant, amount): Promise<Payment> => {
      const id = String(++calls);
      await gate;
      return { id, tenant, amount };
    });
    let parsed = 0;
    let bothParsed!: () => void;
    const parsing = new Promise<void>(resolve => { bothParsed = resolve; });
    const observedRequest = () => {
      const value = request();
      value.json = async () => {
        if (++parsed === 2) bothParsed();
        return { amount: 10 };
      };
      return value;
    };
    const pending = [handler(observedRequest()), handler(observedRequest())];
    await parsing;
    release();
    const responses = await Promise.all(pending);
    expect(await responses[0].json()).toEqual(await responses[1].json());
    expect(calls).toBe(1);
  });

  test("rejects conflicting payload while the original effect is pending", async () => {
    let calls = 0;
    let entered!: () => void;
    let release!: () => void;
    const started = new Promise<void>(resolve => { entered = resolve; });
    const gate = new Promise<void>(resolve => { release = resolve; });
    const handler = createHandler(async (tenant, amount) => {
      const id = String(++calls);
      if (calls === 1) { entered(); await gate; }
      return { id, tenant, amount };
    });
    const original = handler(request());
    await started;
    const conflict = await handler(request("tenant-a", 20));
    release();
    await original;
    expect(conflict.status).toBe(409);
    expect(calls).toBe(1);
  });

  test("allows retry after an unsuccessful side effect", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => {
      if (++calls === 1) throw new Error("synthetic failure before effect");
      return { id: String(calls), tenant, amount };
    });
    expect((await handler(request())).status).toBe(503);
    expect((await handler(request())).status).toBe(201);
    expect(calls).toBe(2);
  });
});

describe("HTTP boundaries and recovery", () => {
  function rawRequest(body: string, tenant = "tenant-a", key = "key-1") {
    return new Request("http://localhost/payments", {
      method: "POST",
      headers: { "x-tenant-id": tenant, "idempotency-key": key },
      body,
    });
  }

  test("rejects invalid JSON, headers and non-positive or non-finite amounts without reserving a key", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    for (const body of ["{", "null", "[]", "{}", '{"amount":"10"}', '{"amount":null}',
      '{"amount":0}', '{"amount":-1}', '{"amount":1e400}', '{"amount":-1e400}']) {
      expect((await handler(rawRequest(body))).status).toBe(400);
    }
    for (const header of ["x-tenant-id", "idempotency-key"]) {
      const missing = request();
      missing.headers.delete(header);
      expect((await handler(missing)).status).toBe(400);
      const empty = request();
      empty.headers.set(header, "");
      expect((await handler(empty)).status).toBe(400);
    }
    expect(calls).toBe(0);
    expect((await handler(request())).status).toBe(201);
    expect(calls).toBe(1);
  });

  test("preserves routing and validates before replaying a completed key", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    expect((await handler(new Request("http://localhost/payments"))).status).toBe(404);
    expect((await handler(new Request("http://localhost/other", { method: "POST" }))).status).toBe(404);
    expect((await handler(request())).status).toBe(201);
    expect((await handler(rawRequest('{"amount":0}'))).status).toBe(400);
    expect((await handler(rawRequest("{"))).status).toBe(400);
    expect(calls).toBe(1);
  });

  test("keeps tenant/key tuples distinct even when delimiters occur in headers", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    const first = await (await handler(request("a:b", 10, "c"))).json();
    const second = await (await handler(request("a", 10, "b:c"))).json();
    expect(first.tenant).toBe("a:b");
    expect(second.tenant).toBe("a");
    expect(second.id).not.toBe(first.id);
    expect(calls).toBe(2);
  });

  test("allows other tenants and keys to finish while one effect is pending", async () => {
    let calls = 0;
    let entered!: () => void;
    let release!: () => void;
    const started = new Promise<void>(resolve => { entered = resolve; });
    const gate = new Promise<void>(resolve => { release = resolve; });
    const handler = createHandler(async (tenant, amount) => {
      const id = String(++calls);
      if (calls === 1) { entered(); await gate; }
      return { id, tenant, amount };
    });
    const original = handler(request());
    await started;
    try {
      const otherTenant = await handler(request("tenant-b", 20));
      const otherKey = await handler(request("tenant-a", 30, "key-2"));
      expect(otherTenant.status).toBe(201);
      expect(await otherTenant.json()).toMatchObject({ tenant: "tenant-b", amount: 20 });
      expect(otherKey.status).toBe(201);
      expect(calls).toBe(3);
    } finally {
      release();
      await original;
    }
  });

  test("shares a pre-effect failure across concurrent waiters, then allows a new payload and replay", async () => {
    let calls = 0;
    let effects = 0;
    let entered!: () => void;
    let release!: () => void;
    const started = new Promise<void>(resolve => { entered = resolve; });
    const gate = new Promise<void>(resolve => { release = resolve; });
    const handler = createHandler(async (tenant, amount) => {
      if (++calls === 1) {
        entered();
        await gate;
        throw new Error("failure before effect");
      }
      return { id: String(++effects), tenant, amount };
    });
    const original = handler(request());
    await started;
    let parsed!: () => void;
    const parsing = new Promise<void>(resolve => { parsed = resolve; });
    const duplicate = request();
    duplicate.json = async () => { parsed(); return { amount: 10 }; };
    const waiter = handler(duplicate);
    await parsing;
    // A completed conflict check also lets the duplicate reach the pending reservation.
    try {
      expect((await handler(request("tenant-a", 20))).status).toBe(409);
      expect(calls).toBe(1);
    } finally {
      release();
    }
    const failures = await Promise.all([original, waiter]);
    for (const response of failures) {
      expect(response.status).toBe(503);
      expect(await response.json()).toEqual({ error: "temporary failure" });
    }
    expect(effects).toBe(0);
    const retry = await handler(request("tenant-a", 20));
    expect(retry.status).toBe(201);
    const payment = await retry.json();
    expect(await (await handler(request("tenant-a", 20))).json()).toEqual(payment);
    expect((await handler(request())).status).toBe(409);
    expect(calls).toBe(2);
    expect(effects).toBe(1);
  });

  test("returns independently readable 201 responses for a burst of identical requests", async () => {
    let calls = 0;
    let release!: () => void;
    let allParsed!: () => void;
    const gate = new Promise<void>(resolve => { release = resolve; });
    const parsing = new Promise<void>(resolve => { allParsed = resolve; });
    const handler = createHandler(async (tenant, amount) => {
      const id = String(++calls);
      await gate;
      return { id, tenant, amount };
    });
    let parsed = 0;
    const pending = Array.from({ length: 32 }, () => {
      const value = request();
      value.json = async () => {
        if (++parsed === 32) allParsed();
        return { amount: 10 };
      };
      return handler(value);
    });
    await parsing;
    release();
    for (const response of await Promise.all(pending)) {
      expect(response.status).toBe(201);
      expect(await response.json()).toEqual({ id: "1", tenant: "tenant-a", amount: 10 });
    }
    const replay = await handler(request());
    expect(replay.status).toBe(201);
    expect(await replay.json()).toEqual({ id: "1", tenant: "tenant-a", amount: 10 });
    expect(calls).toBe(1);
  });

  test("releases a reservation after a synchronous callback throw", async () => {
    let calls = 0;
    const handler = createHandler((tenant, amount) => {
      if (++calls === 1) throw new Error("synchronous failure before effect");
      return Promise.resolve({ id: String(calls), tenant, amount });
    });
    expect((await handler(request())).status).toBe(503);
    const retry = await handler(request("tenant-a", 20));
    expect(retry.status).toBe(201);
    expect(await retry.json()).toEqual({ id: "2", tenant: "tenant-a", amount: 20 });
    expect(calls).toBe(2);
  });
});

