describe("idempotency regression boundaries", () => {
  test("shares a pending failure and permits a concurrent retry wave", async () => {
    let calls = 0;
    let effects = 0;
    let release!: () => void;
    const gate = new Promise<void>(resolve => { release = resolve; });
    const handler = createHandler(async (tenant, amount) => {
      const attempt = ++calls;
      await gate;
      if (attempt === 1) throw new Error("failure before effect");
      effects++;
      return { id: String(attempt), tenant, amount };
    });
    let parsed = 0;
    let allParsed!: () => void;
    const parsing = new Promise<void>(resolve => { allParsed = resolve; });
    const pending = Array.from({ length: 20 }, () => {
      const value = request();
      value.json = async () => {
        if (++parsed === 20) allParsed();
        return { amount: 10 };
      };
      return handler(value);
    });
    await parsing;
    // Let the final parsed request join the operation before releasing it.
    await Promise.resolve();
    release();
    const failures = await Promise.all(pending);
    expect(failures.map(response => response.status)).toEqual(Array(20).fill(503));
    expect(calls).toBe(1);
    expect(effects).toBe(0);

    const retries = await Promise.all(Array.from({ length: 20 }, () => handler(request())));
    expect(retries.map(response => response.status)).toEqual(Array(20).fill(201));
    for (const response of retries) {
      expect(await response.json()).toEqual({ id: "2", tenant: "tenant-a", amount: 10 });
    }
    expect(calls).toBe(2);
    expect(effects).toBe(1);
  });

  test("other tenants and keys progress while an operation is blocked", async () => {
    let calls = 0;
    let release!: () => void;
    let entered!: () => void;
    const gate = new Promise<void>(resolve => { release = resolve; });
    const started = new Promise<void>(resolve => { entered = resolve; });
    const handler = createHandler(async (tenant, amount) => {
      const id = String(++calls);
      if (id === "1") { entered(); await gate; }
      return { id, tenant, amount };
    });
    const original = handler(request());
    await started;
    try {
      const otherTenant = await handler(request("tenant-b", 20));
      expect(otherTenant.status).toBe(201);
      expect(await otherTenant.json()).toEqual({ id: "2", tenant: "tenant-b", amount: 20 });
      const otherKey = await handler(request("tenant-a", 30, "key-2"));
      expect(otherKey.status).toBe(201);
      expect(await otherKey.json()).toEqual({ id: "3", tenant: "tenant-a", amount: 30 });
    } finally {
      release();
      await original;
    }
    expect(calls).toBe(3);
  });

  test("tenant/key tuples cannot collide through separator characters", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    await handler(request("a:b", 10, "c"));
    const response = await handler(request("a", 20, "b:c"));
    expect(response.status).toBe(201);
    expect(await response.json()).toEqual({ id: "2", tenant: "a", amount: 20 });
    expect(calls).toBe(2);
  });

  test("handles synchronous throws before the effect and releases the key", async () => {
    let calls = 0;
    const handler = createHandler((tenant, amount) => {
      if (++calls === 1) throw new Error("synchronous failure before effect");
      return Promise.resolve({ id: "ok", tenant, amount });
    });
    expect((await handler(request())).status).toBe(503);
    const retry = await handler(request("tenant-a", 20));
    expect(retry.status).toBe(201);
    expect(await retry.json()).toEqual({ id: "ok", tenant: "tenant-a", amount: 20 });
    expect(calls).toBe(2);
  });

  test("rejects invalid HTTP input without reserving the key", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    for (const body of ['{', 'null', '[]', '{}', '{"amount":0}', '{"amount":-1}',
      '{"amount":"10"}', '{"amount":null}', '{"amount":true}', '{"amount":1e400}', '{"amount":-1e400}']) {
      const value = request();
      const invalid = new Request(value, { body });
      expect((await handler(invalid)).status).toBe(400);
    }
    for (const header of ["x-tenant-id", "idempotency-key"]) {
      const missing = request();
      missing.headers.delete(header);
      expect((await handler(missing)).status).toBe(400);
      const empty = request();
      empty.headers.set(header, "");
      expect((await handler(empty)).status).toBe(400);
    }
    expect(calls).toBe(0);
    expect((await handler(request())).status).toBe(201);
    expect(calls).toBe(1);
  });

  test("preserves method and route handling without an effect", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    expect((await handler(new Request("http://localhost/payments"))).status).toBe(404);
    expect((await handler(new Request("http://localhost/other", { method: "POST" }))).status).toBe(404);
    expect(calls).toBe(0);
  });
});

