describe("idempotency regression boundaries", () => {
  test("releases the reservation after a synchronous pre-effect throw", async () => {
    let calls = 0;
    const handler = createHandler((tenant, amount) => {
      if (++calls === 1) throw new Error("synchronous failure before effect");
      return Promise.resolve({ id: "recovered", tenant, amount });
    });
    expect((await handler(request())).status).toBe(503);
    const retry = await handler(request("tenant-a", 20));
    expect(retry.status).toBe(201);
    expect(await retry.json()).toEqual({ id: "recovered", tenant: "tenant-a", amount: 20 });
    expect((await handler(request("tenant-a", 10))).status).toBe(409);
    expect(calls).toBe(2);
  });

  test("shares a pending failure across a burst and permits one retry effect", async () => {
    let calls = 0;
    let effects = 0;
    let release!: () => void;
    const gate = new Promise<void>(resolve => { release = resolve; });
    const handler = createHandler(async (tenant, amount) => {
      if (++calls === 1) {
        await gate;
        throw new Error("failure before effect");
      }
      return { id: String(++effects), tenant, amount };
    });
    let parsed = 0;
    let allParsed!: () => void;
    const parsing = new Promise<void>(resolve => { allParsed = resolve; });
    const pending = Array.from({ length: 25 }, () => {
      const value = request();
      value.json = async () => {
        if (++parsed === 25) allParsed();
        return { amount: 10 };
      };
      return handler(value);
    });
    await parsing;
    release();
    const responses = await Promise.all(pending);
    expect(responses.map(response => response.status)).toEqual(Array(25).fill(503));
    expect(calls).toBe(1);
    expect(effects).toBe(0);
    const retries = await Promise.all(Array.from({ length: 25 }, () => handler(request())));
    expect(retries.map(response => response.status)).toEqual(Array(25).fill(201));
    expect(await Promise.all(retries.map(response => response.json())))
      .toEqual(Array(25).fill({ id: "1", tenant: "tenant-a", amount: 10 }));
    expect(calls).toBe(2);
    expect(effects).toBe(1);
  });

  test("does not block another tenant or key behind a pending operation", async () => {
    let entered!: () => void;
    let release!: () => void;
    const started = new Promise<void>(resolve => { entered = resolve; });
    const gate = new Promise<void>(resolve => { release = resolve; });
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => {
      const id = String(++calls);
      if (calls === 1) { entered(); await gate; }
      return { id, tenant, amount };
    });
    const original = handler(request());
    await started;
    try {
      const otherTenant = await handler(request("tenant-b", 20));
      expect(otherTenant.status).toBe(201);
      expect(await otherTenant.json()).toEqual({ id: "2", tenant: "tenant-b", amount: 20 });
      expect((await handler(request("tenant-a", 30, "key-2"))).status).toBe(201);
    } finally {
      release();
      await original;
    }
    expect(calls).toBe(3);
  });

  test("keeps tenant and key boundaries unambiguous", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    await handler(request("a:b", 10, "c"));
    const response = await handler(request("a", 20, "b:c"));
    expect(response.status).toBe(201);
    expect(await response.json()).toEqual({ id: "2", tenant: "a", amount: 20 });
    expect(calls).toBe(2);
  });

  test("rejects malformed input without reserving the key", async () => {
