    await handler(request());
    expect((await handler(request("tenant-a", 20))).status).toBe(409);
    expect(calls).toBe(1);
  });

  test("coalesces concurrent identical requests before awaiting the side effect", async () => {
    let calls = 0;
    let release!: () => void;
    const gate = new Promise<void>(resolve => { release = resolve; });
    const handler = createHandler(async (tenant, amount): Promise<Payment> => {
      const id = String(++calls);
      await gate;
      return { id, tenant, amount };
    });
    let parsed = 0;
    let bothParsed!: () => void;
    const parsing = new Promise<void>(resolve => { bothParsed = resolve; });
    const observedRequest = () => {
      const value = request();
      value.json = async () => {
        if (++parsed === 2) bothParsed();
        return { amount: 10 };
      };
      return value;
    };
    const pending = [handler(observedRequest()), handler(observedRequest())];
    await parsing;
    release();
    const responses = await Promise.all(pending);
    expect(await responses[0].json()).toEqual(await responses[1].json());
    expect(calls).toBe(1);
  });

  test("rejects conflicting payload while the original effect is pending", async () => {
    let calls = 0;
    let entered!: () => void;
    let release!: () => void;
    const started = new Promise<void>(resolve => { entered = resolve; });
    const gate = new Promise<void>(resolve => { release = resolve; });
    const handler = createHandler(async (tenant, amount) => {
      const id = String(++calls);
      if (calls === 1) { entered(); await gate; }
      return { id, tenant, amount };
    });
    const original = handler(request());
    await started;
    const conflict = await handler(request("tenant-a", 20));
    release();
    await original;
    expect(conflict.status).toBe(409);
    expect(calls).toBe(1);
  });

  test("allows retry after an unsuccessful side effect", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => {
      if (++calls === 1) throw new Error("synthetic failure before effect");
      return { id: String(calls), tenant, amount };
    });
    expect((await handler(request())).status).toBe(503);
    expect((await handler(request())).status).toBe(201);
    expect(calls).toBe(2);
  });

  test("shares a pending failure across a burst and coalesces the retry", async () => {
    let calls = 0;
    let entered!: () => void;
    let release!: () => void;
    const started = new Promise<void>(resolve => { entered = resolve; });
    const gate = new Promise<void>(resolve => { release = resolve; });
    const handler = createHandler(async (tenant, amount) => {
      const attempt = ++calls;
      if (attempt === 1) {
        entered();
        await gate;
        throw new Error("failure before effect");
      }
      return { id: String(attempt), tenant, amount };
    });
    const burst = () => Array.from({ length: 40 }, () => {
      const value = request();
      // Deterministic parsing ensures all requests join before the effect starts.
      value.json = async () => ({ amount: 10 });
      return handler(value);
    });
    const pending = burst();
    await started;
    expect(calls).toBe(1);
    release();
    const failures = await Promise.all(pending);
    for (const response of failures) {
      expect(response.status).toBe(503);
      expect(await response.json()).toEqual({ error: "temporary failure" });
    }
    const retries = await Promise.all(burst());
    for (const response of retries) {
      expect(response.status).toBe(201);
      expect(await response.json()).toEqual({ id: "2", tenant: "tenant-a", amount: 10 });
    }
    expect(calls).toBe(2);
  });

  test("other tenants and keys progress while one operation is pending", async () => {
    let calls = 0;
    let entered!: () => void;
    let release!: () => void;
    const started = new Promise<void>(resolve => { entered = resolve; });
    const gate = new Promise<void>(resolve => { release = resolve; });
    const handler = createHandler(async (tenant, amount) => {
      const id = String(++calls);
      if (calls === 1) { entered(); await gate; }
      return { id, tenant, amount };
    });
    const original = handler(request("a:b", 10, "c"));
    await started;
    try {
      // These tuples collide if tenant and key are joined with a colon.
      const otherTenant = await handler(request("a", 20, "b:c"));
      expect(otherTenant.status).toBe(201);
      expect(await otherTenant.json()).toEqual({ id: "2", tenant: "a", amount: 20 });
      const sameKey = await handler(request("a", 30, "c"));
      expect(sameKey.status).toBe(201);
      const otherKey = await handler(request("a:b", 40, "d"));
      expect(otherKey.status).toBe(201);
      expect(calls).toBe(4);
    } finally {
      release();
      expect((await original).status).toBe(201);
    }
  });

  test("releases the reservation after a synchronous throw", async () => {
    let calls = 0;
    const handler = createHandler((tenant, amount) => {
      if (++calls === 1) throw new Error("synchronous failure before effect");
      return Promise.resolve({ id: "recovered", tenant, amount });
    });
    expect((await handler(request())).status).toBe(503);
    // A failed reservation does not bind the key to the failed payload.
    expect((await handler(request("tenant-a", 20))).status).toBe(201);
    expect((await handler(request("tenant-a", 10))).status).toBe(409);
    expect(calls).toBe(2);
  });

  test("rejects invalid HTTP input without reserving the key or invoking the effect", async () => {
    let calls = 0;
    const handler = createHandler(async (tenant, amount) => ({ id: String(++calls), tenant, amount }));
    const bodies = ["{", "null", "[]", "{}", '{"amount":0}', '{"amount":-1}',
      '{"amount":"10"}', '{"amount":true}', '{"amount":null}', '{"amount":1e400}', '{"amount":-1e400}'];
    for (const body of bodies) {
      const value = new Request("http://localhost/payments", {
        method: "POST",
        headers: { "x-tenant-id": "tenant-a", "idempotency-key": "key-1" },
