    const nan = request();
    nan.json = async () => ({ amount: Number.NaN });
    expect((await handler(nan)).status).toBe(400);
    for (const header of ["x-tenant-id", "idempotency-key"]) {
      const missing = request();
      missing.headers.delete(header);
      expect((await handler(missing)).status).toBe(400);
      const empty = request();
      empty.headers.set(header, "");
      expect((await handler(empty)).status).toBe(400);
    }
    expect(calls).toBe(0);
    expect((await handler(request("tenant-a", 0.5))).status).toBe(201);
    expect(calls).toBe(1);
  });

  test("preserves not-found responses for other methods and paths", async () => {
