export type CreatePayment = (tenant: string, amount: number) => Promise<Payment>;

// createPayment must reject only before its effect; ambiguous outcomes need durable coordination.
export function createHandler(createPayment: CreatePayment) {
  const operations = new Map<string, { amount: number; payment: Promise<Payment> }>();
  return async (request: Request): Promise<Response> => {
    const url = new URL(request.url);
    if (request.method !== "POST" || url.pathname !== "/payments") {
      return Response.json({ error: "not found" }, { status: 404 });
    }
    const tenant = request.headers.get("x-tenant-id");
    const key = request.headers.get("idempotency-key");
    let body: unknown;
    try { body = await request.json(); }
    catch { return Response.json({ error: "invalid JSON" }, { status: 400 }); }
    const amount = (body as { amount?: unknown } | null)?.amount;
    if (!tenant || !key || typeof amount !== "number" || !Number.isFinite(amount) || amount <= 0) {
      return Response.json({ error: "invalid input" }, { status: 400 });
    }
    // Tuple encoding avoids collisions between tenant/key pairs containing separators.
    const identity = JSON.stringify([tenant, key]);
    let operation = operations.get(identity);
    if (operation && operation.amount !== amount) {
      return Response.json({ error: "idempotency conflict" }, { status: 409 });
    }
    if (!operation) {
      // Register before invoking the effect, including when it throws synchronously.
      const payment = Promise.resolve().then(() => createPayment(tenant, amount)).catch(error => {
        operations.delete(identity);
        throw error;
      });
      operation = { amount, payment };
      operations.set(identity, operation);
    }
    try {
      const payment = await operation.payment;
      return Response.json(payment, { status: 201 });
    } catch {
      return Response.json({ error: "temporary failure" }, { status: 503 });
    }
  };
}

